    afterEach(() => vi.unstubAllEnvs());
    it('sends actual audio and returns literal timestamped observations', async () => {
        generateContent.mockResolvedValue({ text: JSON.stringify(result) });
        const response = await POST(request());
        expect(response.status).toBe(200);
        expect(await response.json()).toEqual({ model: 'gemini-3.1-pro-preview', ...result });
        const call = generateContent.mock.calls[0][0];
        expect(call.contents[0].parts[0].inlineData).toEqual({ mimeType: 'audio/wav', data: wav().toString('base64') });
        expect(call.config.systemInstruction).toMatch(/untrusted/i);
        expect(call.config.httpOptions.timeout).toBe(90000);
        expect(response.headers.get('cache-control')).toBe('no-store');
    });
    it('honours the separate audio model override', async () => {
        vi.stubEnv('GEMINI_AUDIO_MODEL', 'test-audio-model');
        generateContent.mockResolvedValue({ text: JSON.stringify(result) });
        const response = await POST(request());
        expect((await response.json()).model).toBe('test-audio-model');
    });
    it.each([
        { ...result, fillers: [{ ...result.fillers[0], endSeconds: 2 }] },
        { ...result, fillers: [result.fillers[0], result.fillers[0]] },
        { ...result, fillers: [{ ...result.fillers[0], startSeconds: -1 }] },
        { ...result, fillers: [{ ...result.fillers[0], word: 'inventedword' }] },
        { ...result, extra: 'unexpected' },
    ])('rejects malformed or ungrounded model observations', async output => {
        generateContent.mockResolvedValue({ text: JSON.stringify(output) });
        expect((await POST(request())).status).toBe(502);
    });
    it('rejects missing or invalid JSON output', async () => {
        for (const text of [undefined, 'not json']) {
            generateContent.mockResolvedValue({ text });
            expect((await POST(request())).status).toBe(502);
        }
    });
    it('returns provider failure without revealing its message', async () => {
        generateContent.mockRejectedValue(new Error('secret provider text'));
        const response = await POST(request());
        expect(response.status).toBe(502);
        expect(await response.text()).not.toContain('secret provider text');
    });
    it('requires a server API key', async () => {
        vi.stubEnv('GEMINI_API_KEY', undefined);
        expect((await POST(request())).status).toBe(503);
    });
    it('rejects cross-origin requests before contacting Gemini', async () => {
        expect((await POST(request(wav(), { origin: 'https://attacker.test' }))).status).toBe(403);
        expect(generateContent).not.toHaveBeenCalled();
    });
    it('rate limits requests before contacting Gemini', async () => {
        for (let i = 0; i < 60; i++) await POST(request(Buffer.alloc(1)));
        expect((await POST(request())).status).toBe(429);
        expect(generateContent).not.toHaveBeenCalled();
    });
    it('rejects oversized and invalid audio before contacting Gemini', async () => {
        expect((await POST(request(wav(61)))).status).toBe(413);
